class PlayerObject extends ModelObject {
  playerClass = PlayerClass.DarkKnight;
  HelmMask;
  Helm;
  Armor;
  Pants;
  Gloves;
  Boots;
  Weapon1;
  Weapon2;
  Wings;
  IsInteractable = false;
  constructor(scene2, parent) {
    super(scene2, parent);
    this.BoundingBoxLocal = new BoundingBox(
      new Vector3(-0.4, 0, -0.4),
      new Vector3(0.4, 1.2, 0.4)
    );
    this.CurrentAction = PlayerAction.PLAYER_SKILL_INFERNO;
    this.HelmMask = new ModelObject(scene2, this._node);
    this.Helm = new ModelObject(scene2, this._node);
    this.Armor = new ModelObject(scene2, this._node);
    this.Pants = new ModelObject(scene2, this._node);
    this.Gloves = new ModelObject(scene2, this._node);
    this.Boots = new ModelObject(scene2, this._node);
    this.Weapon1 = new ModelObject(scene2, this._node);
    this.Weapon2 = new ModelObject(scene2, this._node);
    this.Wings = new ModelObject(scene2, this._node);
    this.HelmMask.NodeNamePrefix = "HelmMask_";
    this.Helm.NodeNamePrefix = "Helm_";
    this.Armor.NodeNamePrefix = "Armor_";
    this.Pants.NodeNamePrefix = "Pants_";
    this.Gloves.NodeNamePrefix = "Gloves_";
    this.Boots.NodeNamePrefix = "Boots_";
    this.Weapon1.NodeNamePrefix = "Weapon1_";
    this.Weapon2.NodeNamePrefix = "Weapon2_";
    this.Wings.NodeNamePrefix = "Wings_";
    const objs = [
      this.HelmMask,
      this.Helm,
      this.Armor,
      this.Pants,
      this.Gloves,
      this.Boots,
      this.Weapon1,
      this.Weapon2,
      this.Wings
    ];
    objs.forEach((obj) => {
      obj.setParent(this);
      obj.LinkParent = true;
    });
    this.Wings.LinkParent = false;
    this.Wings.ParentBoneLink = 47;
    this.Wings.SkipBoundingBox = true;
    this.Weapon1.SkipBoundingBox = true;
    this.Weapon2.SkipBoundingBox = true;
    this.HelmMask.SkipBoundingBox = true;
    this.Pants.SkipBoundingBox = true;
    this.Gloves.SkipBoundingBox = true;
    this.Helm.SkipBoundingBox = true;
    this.Weapon1.LinkParent = false;
    this.Weapon1.ParentBoneLink = 33;
  }
  async init(world2, entity) {
    await super.init(world2, entity);
    this.load(await loadGLTF("Player/player.glb", world2));
    this.Ready = false;
    await this.updateBodyPartClassesAsync();
    this.setActionSpeed(PlayerAction.PLAYER_WALK_MALE, 2);
    this.setActionSpeed(PlayerAction.PLAYER_WALK_FEMALE, 2);
    this.Ready = true;
  }
  async updateBodyPartClassesAsync() {
    await this.setBodyPartsAsync(
      "Player/",
      "HelmClass",
      "ArmorClass",
      "PantClass",
      "GloveClass",
      "BootClass",
      this.playerClass
    );
  }
  async setDefaultHelm() {
    await this.setBodyPartsAsync(
      "Player/",
      "HelmClass",
      "",
      "",
      "",
      "",
      this.playerClass
    );
  }
  async setDefaultMask() {
    this.HelmMask.Unload();
  }
  async setDefaultArmor() {
    await this.setBodyPartsAsync(
      "Player/",
      "",
      "ArmorClass",
      "",
      "",
      "",
      this.playerClass
    );
  }
  async setDefaultPants() {
    await this.setBodyPartsAsync(
      "Player/",
      "",
      "",
      "PantClass",
      "",
      "",
      this.playerClass
    );
  }
  async setDefaultGloves() {
    await this.setBodyPartsAsync(
      "Player/",
      "",
      "",
      "",
      "GloveClass",
      "",
      this.playerClass
    );
  }
  async setDefaultBoots() {
    await this.setBodyPartsAsync(
      "Player/",
      "",
      "",
      "",
      "",
      "BootClass",
      this.playerClass
    );
  }
  async setBodyPartsAsync(pathPrefix, helmPrefix, armorPrefix, pantPrefix, glovePrefix, bootPrefix, skinIndex) {
    const fileSuffix = skinIndex.toString().padStart(2, "0");
    await Promise.all([
      !helmPrefix ? Promise.resolve() : this.loadPartAsync(
        pathPrefix,
        this.Helm,
        `${helmPrefix}${fileSuffix}.glb`
      ),
      !armorPrefix ? Promise.resolve() : this.loadPartAsync(
        pathPrefix,
        this.Armor,
        `${armorPrefix}${fileSuffix}.glb`
      ),
      !pantPrefix ? Promise.resolve() : this.loadPartAsync(
        pathPrefix,
        this.Pants,
        `${pantPrefix}${fileSuffix}.glb`
      ),
      !glovePrefix ? Promise.resolve() : this.loadPartAsync(
        pathPrefix,
        this.Gloves,
        `${glovePrefix}${fileSuffix}.glb`
      ),
      !bootPrefix ? Promise.resolve() : this.loadPartAsync(
        pathPrefix,
        this.Boots,
        `${bootPrefix}${fileSuffix}.glb`
      )
    ]);
  }
  async loadPartAsync(dir, part, modelPath, itemLvl, isExcellent2, isDivine) {
    const gltf = await loadGLTF(dir + modelPath, Store.world);
    part.load(gltf);
    gltf.mesh.isPickable = this.IsInteractable;
    const meshes = part.getMeshes(true);
    meshes.forEach((mesh) => {
      mesh.isPickable = this.IsInteractable;
      mesh.metadata ??= {};
      mesh.metadata.itemLvl = itemLvl ?? 0;
      mesh.metadata.isExcellent = isExcellent2 ?? false;
      mesh.metadata.isDivine = isDivine ?? false;
    });
  }
  Update(gameTime) {
    super.Update(gameTime);
    for (const child of this.Children) {
      child.Update(gameTime);
    }
  }
  Draw(gameTime) {
    super.Draw(gameTime);
    for (const child of this.Children) {
      child.Draw(gameTime);
    }
  }
}
