EventBus.on("ObjectWalked", (packet) => {
  const p2 = new ObjectWalkedPacket(packet);
  const world2 = Store.world;
  if (!world2) return;
  const maskedId = p2.ObjectId & 32767;
  const obj = world2.netObjsQuery.entities.find((e) => e.netId === maskedId);
  if (!obj) return;
  if (obj.localPlayer) return;
  if (obj.playerMoveTo) {
    obj.playerMoveTo.handled = false;
    obj.playerMoveTo.point.x = p2.TargetX;
    obj.playerMoveTo.point.y = p2.TargetY;
  } else {
    obj.transform.pos.x = p2.TargetX;
    obj.transform.pos.z = p2.TargetY;
  }
  obj.transform.rot.y = convertDirectionToAngle(p2.TargetRotation);
  const dirs = new Array(p2.StepCount).fill(0);
  for (let i = 0; i < p2.StepCount; i++) {
    dirs[i] = p2.StepData.getUint8(i);
  }
  console.log(
    `ObjectWalked: ${maskedId}, steps: ${p2.StepCount}, directions: ${dirs.join(
      "->"
    )}, x: ${p2.TargetX}, y: ${p2.TargetY}, rotation: ${p2.TargetRotation}`,
    packet
  );
});
